import React from 'react';

function App() {
  return (
    <div style={{ 
      display: 'flex', 
      justifyContent: 'center', 
      alignItems: 'center', 
      height: '100vh',
      background: '#0a0e17',
      color: 'white',
      fontFamily: 'Arial'
    }}>
      <div style={{ textAlign: 'center' }}>
        <h1 style={{ color: '#4CAF50' }}>📈 Trading Platform</h1>
        <p>React is working!</p>
        <p>Now let's build your trading app.</p>
      </div>
    </div>
  );
}

export default App;
